local GrainMillMaker = {}
local PRODUCTS = {
    simple_stone_grain_mill = { name = "Preprost kamnit mlin za žito", stoneCost = 4, woodCost = 2, time = 6, cost = 200, food = 15, happiness = 1, description = "Preprost kamnit mlin za mletje žita." },
    iron_reinforced_mill = { name = "Železnookrepljen mlin", stoneCost = 3, ironCost = 2, woodCost = 2, time = 9, cost = 480, food = 25, happiness = 2, prestige = 2, description = "Železnookrepljen mlin za trgovce." },
    silver_geared_mill = { name = "Srebrnozobčani mlin", stoneCost = 3, ironCost = 2, silverCost = 1, woodCost = 2, time = 13, cost = 1100, food = 38, happiness = 2, prestige = 6, description = "Srebrnozobčani mlin za plemiče." },
    gold_trimmed_mill = { name = "Zlatookrasni mlin", stoneCost = 3, ironCost = 2, goldCost = 1, silverCost = 1, woodCost = 2, time = 17, cost = 2500, food = 52, happiness = 3, prestige = 14, description = "Zlatookrasni mlin za visoke plemiče." },
    jewel_set_mill = { name = "Draguljasta mlin", stoneCost = 3, ironCost = 2, goldCost = 1, silverCost = 1, woodCost = 2, jewelCost = 1, time = 21, cost = 5200, food = 68, happiness = 5, prestige = 27, description = "Mlin z draguljem za visoko plemstvo." },
    royal_grand_grain_mill = { name = "Kraljevski veliki mlin za žito", stoneCost = 4, ironCost = 3, goldCost = 2, silverCost = 2, woodCost = 2, jewelCost = 2, pearlCost = 2, time = 28, cost = 11000, food = 88, happiness = 12, prestige = 58, description = "Veliki kraljevski mlin za žito z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    mill_workshop = { name = "Mlinska delavnica", cost = { gold = 320, wood = 180, stone = 180, iron = 6 }, upkeep = 7, qualityBonus = 5 },
    milling_loft = { name = "Mlinska podstrešje", cost = { gold = 1100, wood = 320, stone = 320, silver = 6, iron = 8 }, upkeep = 26, qualityBonus = 18 },
    master_miller_atelier = { name = "Mojstrski mlinski atelje", cost = { gold = 2900, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 68, qualityBonus = 30 },
    royal_mill_palace = { name = "Kraljevska mlinska palača", cost = { gold = 12500, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 250, qualityBonus = 55, prestigeBonus = 50 },
}
GrainMillMaker.stoneStock = 20; GrainMillMaker.ironStock = 14; GrainMillMaker.woodStock = 14; GrainMillMaker.silverStock = 6; GrainMillMaker.goldStock = 6; GrainMillMaker.jewelStock = 4; GrainMillMaker.pearlStock = 4
GrainMillMaker.productStock = {}; GrainMillMaker.buildings = {}; GrainMillMaker.maker = nil; GrainMillMaker.activeMaking = {}; GrainMillMaker.totalProducts = 0; GrainMillMaker.dayTimer = 0
function GrainMillMaker.init() GrainMillMaker.stoneStock=20; GrainMillMaker.ironStock=14; GrainMillMaker.woodStock=14; GrainMillMaker.silverStock=6; GrainMillMaker.goldStock=6; GrainMillMaker.jewelStock=4; GrainMillMaker.pearlStock=4; GrainMillMaker.productStock={}; GrainMillMaker.buildings={}; GrainMillMaker.maker=nil; GrainMillMaker.activeMaking={}; GrainMillMaker.totalProducts=0; GrainMillMaker.dayTimer=0; print("[GrainMillMaker] Royal Grain Mill Maker System initialized (6 products, 4 buildings)") end
function GrainMillMaker.hireMaker(n,s) s=s or math.random(55,90); local c=600+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GrainMillMaker.maker={name=n or ("Mlinar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mlinar najet: %s (spretnost: %d)",GrainMillMaker.maker.name,s),"success") end; return true end
function GrainMillMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GrainMillMaker.build(id) local ok,e=GrainMillMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GrainMillMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GrainMillMaker.getQualityBonus() local b=0; for _,bd in ipairs(GrainMillMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GrainMillMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.stoneCost and GrainMillMaker.stoneStock<(d.stoneCost or 0) then return false,"Premalo kamna" end; if d.ironCost and GrainMillMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.woodCost and GrainMillMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and GrainMillMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GrainMillMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GrainMillMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GrainMillMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GrainMillMaker.buildings==0 then return false,"Potrebna mlinska delavnica" end; if not GrainMillMaker.maker then return false,"Potreben mlinar" end; return true end
function GrainMillMaker.make(pt,qty) qty=qty or 1; local ok,e=GrainMillMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.stoneCost then GrainMillMaker.stoneStock=GrainMillMaker.stoneStock-d.stoneCost*qty end; if d.ironCost then GrainMillMaker.ironStock=GrainMillMaker.ironStock-d.ironCost*qty end; if d.woodCost then GrainMillMaker.woodStock=GrainMillMaker.woodStock-d.woodCost*qty end; if d.silverCost then GrainMillMaker.silverStock=GrainMillMaker.silverStock-d.silverCost*qty end; if d.goldCost then GrainMillMaker.goldStock=GrainMillMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GrainMillMaker.jewelStock=GrainMillMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GrainMillMaker.pearlStock=GrainMillMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GrainMillMaker.maker then t=math.max(1,t-math.floor(GrainMillMaker.maker.skill/12)) end; table.insert(GrainMillMaker.activeMaking,{id="grainmill_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GrainMillMaker.completeMaking(m) local q=1.0+(GrainMillMaker.getQualityBonus()/100); if GrainMillMaker.maker then q=q+(GrainMillMaker.maker.skill/140) end; q=math.min(2.5,q); GrainMillMaker.productStock[m.productType]=(GrainMillMaker.productStock[m.productType] or 0)+m.quantity; GrainMillMaker.totalProducts=GrainMillMaker.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GrainMillMaker.maker then GrainMillMaker.maker.itemsMade=GrainMillMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GrainMillMaker.maker.skill=math.min(100,GrainMillMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mlin izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"grainmill.completed",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function GrainMillMaker.update(dt) if not _G.state then return end; GrainMillMaker.dayTimer=GrainMillMaker.dayTimer+dt; if GrainMillMaker.dayTimer>=30 then GrainMillMaker.dayTimer=0; for i=#GrainMillMaker.activeMaking,1,-1 do local m=GrainMillMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GrainMillMaker.completeMaking(m); table.remove(GrainMillMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GrainMillMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GrainMillMaker.maker then tu=tu+16 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GrainMillMaker.getStats() return {stoneStock=GrainMillMaker.stoneStock,ironStock=GrainMillMaker.ironStock,woodStock=GrainMillMaker.woodStock,silverStock=GrainMillMaker.silverStock,goldStock=GrainMillMaker.goldStock,jewelStock=GrainMillMaker.jewelStock,pearlStock=GrainMillMaker.pearlStock,productStock=GrainMillMaker.productStock,numBuildings=#GrainMillMaker.buildings,hasMaker=GrainMillMaker.maker~=nil,makerName=GrainMillMaker.maker and GrainMillMaker.maker.name or "—",makerSkill=GrainMillMaker.maker and GrainMillMaker.maker.skill or 0,activeMaking=#GrainMillMaker.activeMaking,totalProducts=GrainMillMaker.totalProducts} end
return GrainMillMaker
